CREATE INDEX IF NOT EXISTS i_gifts__newsletterId__status__createdAt_d ON c_gifts (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.status') ASC, json_extract(data, '$.createdAt') DESC);
